#include "stdlib/blas/base/ssymv.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/blas/base/xerbla.h"
#include "stdlib/strided/base/stride2offset.h"

/**
* Performs the matrix-vector operation `Y = α*A*X + β*Y` where `α` and `β` are scalars, `X` and `Y` are `N` element vectors, and `A` is an `N` by `N` symmetric matrix.
*
* @param order     storage layout
* @param uplo      specifies whether the upper or lower triangular part of the symmetric matrix `A` is supplied
* @param N         number of elements along each dimension of `A`
* @param alpha     scalar constant
* @param A         input matrix
* @param LDA       stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
* @param X         first input array
* @param strideX   `X` stride length
* @param beta      scalar constant
* @param Y         second input array
* @param strideY   `Y` stride length
*/
void API_SUFFIX(c_ssymv)( const CBLAS_LAYOUT order, const CBLAS_UPLO uplo, const CBLAS_INT N, const float alpha, const float *A, const CBLAS_INT LDA, const float *X, const CBLAS_INT strideX, const float beta, float *Y, const CBLAS_INT strideY ) {
	CBLAS_INT vala;
	CBLAS_INT sa1;
	CBLAS_INT sa2;
	CBLAS_INT ox;
	CBLAS_INT oy;

	// Perform input argument validation...
	if ( order != CblasRowMajor && order != CblasColMajor ) {
		c_xerbla( 1, "c_ssymv", "Error: invalid argument. First argument must be a valid layout. Value: `%d`.", order );
		return;
	}
	if ( uplo != CblasLower && uplo != CblasUpper ) {
		c_xerbla( 2, "c_ssymv", "Error: invalid argument. Second argument must specify whether to reference the lower or upper triangular matrix. Value: `%d`.", uplo );
		return;
	}
	if ( N < 0 ) {
		c_xerbla( 3, "c_ssymv", "Error: invalid argument. Third argument must be a nonnegative integer. Value: `%d`.", N );
		return;
	}
	// max(1, N)
	if ( N < 1 ) {
		vala = 1;
	} else {
		vala = N;
	}
	if ( LDA < vala ) {
		c_xerbla( 10, "c_ssymv", "Error: invalid argument. Sixth argument must be greater than or equal to max(1,%d). Value: `%d`.", vala, LDA );
		return;
	}
	if ( strideX == 0 ) {
		c_xerbla( 8, "c_ssymv", "Error: invalid argument. Eighth argument must be nonzero. Value: `%d`.", strideX );
		return;
	}
	if ( strideY == 0 ) {
		c_xerbla( 11, "c_ssymv", "Error: invalid argument. Eleventh argument must be nonzero. Value: `%d`.", strideY );
		return;
	}
	// Check whether we can avoid computation altogether...
	if ( N == 0 || ( alpha == 0.0f && beta == 1.0f ) ) {
		return;
	}
	if ( order == CblasColMajor ) {
		sa1 = 1;
		sa2 = LDA;
	} else { // order === 'row-major'
		sa1 = LDA;
		sa2 = 1;
	}
	ox = stdlib_strided_stride2offset( N, strideX );
	oy = stdlib_strided_stride2offset( N, strideY );
	API_SUFFIX(c_ssymv_ndarray)( uplo, N, alpha, A, sa1, sa2, 0, X, strideX, ox, beta, Y, strideY, oy );
	return;
}
